// Helper: sift-down (heapify) for min-heap
auto heapify = [arr](int n, int i) mutable {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] < arr[smallest])
        smallest = left;
    if (right < n && arr[right] < arr[smallest])
        smallest = right;

    if (smallest != i) {
        std::swap(arr[i], arr[smallest]);
        // Recursively heapify the affected subtree
        int current = smallest;
        while (true) {
            int l = 2 * current + 1;
            int r = 2 * current + 2;
            int next = current;

            if (l < n && arr[l] < arr[next])
                next = l;
            if (r < n && arr[r] < arr[next])
                next = r;

            if (next == current) break;

            std::swap(arr[current], arr[next]);
            current = next;
        }
    }
};

// Build min-heap: start from last non-leaf node and sift-down
for (int i = size / 2 - 1; i >= 0; --i) {
    heapify(size, i);
}

